initJs:
function(container, apiUrl, tables) {
  // 店舗データを読み込んでドロップダウンに設定
  function loadStores() {
    const storeSelect = container.querySelector('#target-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector('#learning-rate');
    const display = container.querySelector('#learning-rate-value');
    slider.addEventListener('input', () => {
      display.textContent = parseFloat(slider.value).toFixed(5);
    });
  }

  // 重み付けの合計値計算
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll('.weight-input');
    const totalDisplay = container.querySelector('#weight-total');

    function calculateTotal() {
      let total = 0;
      weightInputs.forEach(input => {
        total += parseInt(input.value) || 0;
      });
      totalDisplay.textContent = total;
      totalDisplay.style.color = total === 100 ? 'var(--text)' : '#ff6a00';
    }

    weightInputs.forEach(input => {
      input.addEventListener('input', calculateTotal);
    });
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // モデル名チェック
    const modelName = container.querySelector('#model-name').value.trim();
    if (!modelName) {
      errors.push('モデル名を入力してください');
    }

    // 対象店舗チェック
    const targetStore = container.querySelector('#target-store').value;
    if (!targetStore) {
      errors.push('対象店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('#product-categories input[type="checkbox"]:checked');
    if (selectedCategories.length === 0) {
      errors.push('対象商品カテゴリを選択してください');
    }

    // 学習期間チェック
    const startDate = container.querySelector('#learning-start-date').value;
    const endDate = container.querySelector('#learning-end-date').value;
    if (!startDate || !endDate) {
      errors.push('学習期間を設定してください');
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > end) {
        errors.push('開始日は終了日より前の日付を設定してください');
      }
      if (start > today || end > today) {
        errors.push('学習期間に未来の日付は設定できません');
      }
    }

    // 予測期間チェック
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked');
    if (!predictionPeriod) {
      errors.push('予測期間を選択してください');
    }

    // データソースチェック
    const selectedDataSources = container.querySelectorAll('#data-sources input[type="checkbox"]:checked');
    if (selectedDataSources.length === 0) {
      errors.push('データソースを選択してください');
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector('#algorithm').value;
    if (!algorithm) {
      errors.push('アルゴリズムを選択してください');
    }

    // 精度目標値チェック
    const accuracyTarget = parseInt(container.querySelector('#accuracy-target').value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push('モデル精度目標値は0-100%の範囲で設定してください');
    }

    // 重み付け合計チェック
    const weightTotal = parseInt(container.querySelector('#weight-total').textContent);
    if (weightTotal !== 100) {
      errors.push('重み付けの合計値は100%にしてください');
    }

    // 季節性パラメータの数値チェック
    const seasonalStrength = container.querySelector('#seasonal-strength').value;
    const trendStrength = container.querySelector('#trend-strength').value;
    if (isNaN(seasonalStrength) || isNaN(trendStrength)) {
      errors.push('季節性パラメータには数値を入力してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorDiv = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorDiv.innerHTML = '<ul>' + errors.map(err => `<li>${err}</li>`).join('') + '</ul>';
      errorDiv.classList.remove('hidden');
    } else {
      errorDiv.classList.add('hidden');
    }
  }

  // フォームデータ収集
  function collectFormData() {
    const selectedCategories = Array.from(container.querySelectorAll('#product-categories input[type="checkbox"]:checked'))
      .map(cb => cb.value);
    const selectedDataSources = Array.from(container.querySelectorAll('#data-sources input[type="checkbox"]:checked'))
      .map(cb => cb.value);
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked')?.value;

    const weights = {};
    container.querySelectorAll('.weight-input').forEach(input => {
      weights[input.dataset.factor] = parseInt(input.value) || 0;
    });

    return {
      モデル名: container.querySelector('#model-name').value.trim(),
      対象店舗ID: container.querySelector('#target-store').value,
      対象商品カテゴリ: selectedCategories.join(','),
      学習期間開始日: container.querySelector('#learning-start-date').value,
      学習期間終了日: container.querySelector('#learning-end-date').value,
      予測期間: predictionPeriod,
      使用データソース: selectedDataSources.join(','),
      アルゴリズム: container.querySelector('#algorithm').value,
      学習率: parseFloat(container.querySelector('#learning-rate').value),
      重み付け設定: JSON.stringify(weights),
      季節性強度: parseFloat(container.querySelector('#seasonal-strength').value),
      トレンド強度: parseFloat(container.querySelector('#trend-strength').value),
      異常値除外フラグ: container.querySelector('#exclude-outliers').checked,
      祝日除外フラグ: container.querySelector('#exclude-holidays').checked,
      特別イベント除外フラグ: container.querySelector('#exclude-special-events').checked,
      精度目標値: parseInt(container.querySelector('#accuracy-target').value),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };
  }

  // フォームリセット
  function resetForm() {
    container.querySelector('#model-name').value = '';
    container.querySelector('#target-store').value = '';
    container.querySelectorAll('#product-categories input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#learning-start-date').value = '';
    container.querySelector('#learning-end-date').value = '';
    container.querySelectorAll('input[name="prediction-period"]').forEach(rb => rb.checked = false);
    container.querySelectorAll('#data-sources input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#algorithm').value = '';
    container.querySelector('#learning-rate').value = '0.01';
    container.querySelector('#learning-rate-value').textContent = '0.01';
    container.querySelectorAll('.weight-input').forEach((input, index) => {
      input.value = [40, 20, 20, 20][index];
    });
    container.querySelector('#seasonal-strength').value = '1.0';
    container.querySelector('#trend-strength').value = '1.0';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#accuracy-target').value = '85';
    container.querySelector('#weight-total').textContent = '100';
    container.querySelector('#error-messages').classList.add('hidden');
  }

  // 初期化
  loadStores();
  updateLearningRateDisplay();
  updateWeightTotal();

  // 保存ボタンのイベントリスナー
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const errors = validateForm();
    showErrors(errors);

    if (errors.length === 0) {
      const formData = collectFormData();

      // 既存モデル名チェック（簡易実装）
      const existingModels = await window.aivicApi.list(0);
      if (existingModels && existingModels.some(model => model.モデル名 === formData.モデル名)) {
        showErrors(['このモデル名は既に使用されています']);
        return;
      }

      const saved = await window.aivicApi.save(0, formData);
      if (saved) {
        alert('モデルが正常に作成されました');
        resetForm();
      }
    }
  });

  // テストボタンのイベントリスナー
  container.querySelector('#btn-test').addEventListener('click', () => {
    const errors = validateForm();
    if (errors.length === 0) {
      window.showScreen('scr-1778591999045'); // モデルテスト機能画面
    } else {
      showErrors(errors);
    }
  });

  // リセットボタンのイベントリスナー
  container.querySelector('#btn-reset').addEventListener('click', () => {
    if (confirm('入力内容をリセットしますか？')) {
      resetForm();
    }
  });
}
